insert into practice_exercises (id, subject_name, level, title, source) values
  ('5a3d4480-353e-4e41-a142-447e160dc42c', $$Natuurkunde$$, $$HAVO$$, $$Sluis van Fankel$$, $$HAVO Natuurkunde 2016-II$$),
  ('c2a80c63-ba2b-428e-88b6-6f95c76f731c', $$Natuurkunde$$, $$HAVO$$, $$Wieg$$, $$HAVO Natuurkunde 2016-II$$),
  ('16c00dfe-9958-49bb-ba90-c8180f1ed115', $$Natuurkunde$$, $$HAVO$$, $$Bliksem$$, $$HAVO Natuurkunde 2016-II$$),
  ('e0a40eb4-54fe-4a3f-b504-3fc4ffdc8216', $$Natuurkunde$$, $$HAVO$$, $$Aerogel$$, $$HAVO Natuurkunde 2016-II$$),
  ('ac555faa-7897-450c-8dca-3e3856d1e765', $$Natuurkunde$$, $$HAVO$$, $$Airbus E-fan$$, $$HAVO Natuurkunde 2016-II$$);

insert into practice_context_blocks (id, exercise_id, label, image_url, image_width, text_content, block_type) values
  ('f023a6cc-f8ee-4ad7-a8a8-60ef21b6883f', '5a3d4480-353e-4e41-a142-447e160dc42c', $$figuur 1 en 2 — schip vaart de sluis in en het water in de sluis zakt$$,
   $$natuurkunde-havo-2016-ii-sluis-van-fankel-context1.png$$, 452,
   $$Tijdens een boottochtje over de Moezel van Beilstein naar Cochem passeert een schip bij Fankel een sluis. Het schip vaart de sluis in (zie figuur 1), het water in de sluis zakt (zie figuur 2), en na enige tijd kan het schip de sluis weer verlaten. In de sluis ligt het schip stil.

figuur 1: foto van het schip dat de sluis invaart.
figuur 2: foto van hetzelfde schip in de sluis, met het water gezakt.$$, 'inline'),
  ('4507058b-42ce-4658-a82c-408d75675ad1', '5a3d4480-353e-4e41-a142-447e160dc42c', $$twee (v,t)-diagrammen (heenreis en terugreis) op de uitwerkbijlage; snelheid van het schip t.o.v. de oever$$,
   $$natuurkunde-havo-2016-ii-sluis-van-fankel-context2.png$$, 432,
   $$Een passagier op het schip heeft twee (v,t)-diagrammen gemaakt: één van de heenreis en één van de terugreis. Deze diagrammen zijn op de uitwerkbijlage gegeven. Hierin is de snelheid van het schip gegeven ten opzichte van de oever.$$, 'inline'),
  ('4f694978-5679-4fc8-ad97-afa8b3eb09ac', '5a3d4480-353e-4e41-a142-447e160dc42c', $$de Moezel is een stromende rivier; de snelheid van het schip t.o.v. het water is in beide richtingen even groot$$,
   $$natuurkunde-havo-2016-ii-sluis-van-fankel-context3.png$$, 446,
   $$De Moezel is een stromende rivier. De snelheid van het schip ten opzichte van het water is in beide richtingen even groot.$$, 'inline'),
  ('26bd7873-1c61-4ad1-867b-fd127df03ca3', '5a3d4480-353e-4e41-a142-447e160dc42c', $$waterhoogte stijgt op de terugweg met 7,0 m; (h,t)-diagram van het stijgen van het water op de uitwerkbijlage$$,
   $$natuurkunde-havo-2016-ii-sluis-van-fankel-context4.png$$, 409,
   $$Bij deze sluis neemt de waterhoogte op de terugweg met 7,0 m toe. Het stijgen van het water in de sluis als functie van de tijd is in een (h,t)-diagram op de uitwerkbijlage gegeven.$$, 'inline'),
  ('ba9d288d-04b7-4945-b918-07a9cdf45842', '5a3d4480-353e-4e41-a142-447e160dc42c', $$figuur 3 — sluisdeuren in bovenaanzicht (open/gesloten) met hydraulische cilinder, kracht F onder hoek α$$,
   $$natuurkunde-havo-2016-ii-sluis-van-fankel-context5.png$$, 471,
   $$In figuur 3 zijn de sluisdeuren in bovenaanzicht schematisch getekend. In het bovenste deel van figuur 3 staan de sluisdeuren open, in het onderste deel zijn ze gesloten. De sluisdeuren worden bediend met hydraulische cilinders: deze hebben stangen die in en uit kunnen schuiven. Tijdens het sluiten van de sluisdeuren heeft het water rond een sluisdeur dezelfde hoogte. De kracht van de hydraulische cilinder op een sluisdeur is tijdens het sluiten van de sluisdeuren steeds even groot.

Op een bepaald tijdstip worden de sluisdeuren gesloten.

figuur 3: bovenaanzicht van de sluisdeuren, open (boven) en gesloten (onder), met de hydraulische cilinder, de kracht F en de hoek α aangegeven.$$, 'inline'),
  ('9f985632-6065-4bb3-81b9-4366a9c3b799', '5a3d4480-353e-4e41-a142-447e160dc42c', $$figuur 4 — stuw naast de sluis; hoogteverschil 7,0 m; bij 400 m³ water per seconde maximaal vermogen 16,4 MW$$,
   $$natuurkunde-havo-2016-ii-sluis-van-fankel-context6.png$$, 512,
   $$Naast de sluis ligt in de rivier een stuw. Zie figuur 4. Een stuw wordt gebouwd tussen twee delen van een rivier met een hoogteverschil. Dit hoogteverschil wordt gebruikt om met behulp van een waterkrachtcentrale elektrische energie op te wekken. Het hoogteverschil in deze stuw is 7,0 m. Als er 400 m³ water per seconde door de stuw gaat, levert de stuw zijn maximale elektrische vermogen van 16,4 MW. Het snelheidsverschil van het water voor en na de stuw is te verwaarlozen.

figuur 4: luchtfoto van de sluis en de stuw in de rivier.$$, 'inline'),
  ('6ef75474-5291-4cce-b141-3ad05ea09077', '5a3d4480-353e-4e41-a142-447e160dc42c', $$gemiddeld 209 m³ water per seconde door de stuw; vermogen evenredig met debiet; huishouden gebruikt 3750 kWh per jaar$$,
   $$natuurkunde-havo-2016-ii-sluis-van-fankel-context7.png$$, 443,
   $$Gemiddeld stroomt er 209 m³ water per seconde door de stuw. Het opgewekte vermogen is evenredig met de hoeveelheid water per seconde. Het rendement van de stuw is bij 209 m³ water per seconde niet hetzelfde als bij 400 m³ water per seconde. Een huishouden gebruikt gemiddeld 3750 kWh per jaar aan elektrische energie.$$, 'inline'),
  ('328ba86f-72d3-4b44-bc02-6f2c27d5d9d1', '5a3d4480-353e-4e41-a142-447e160dc42c', $$uitwerkbijlage vraag 1 — leeg (v,t)-diagram van de heenreis$$,
   $$natuurkunde-havo-2016-ii-sluis-van-fankel-uitwerkbijlage-vraag1.png$$, 469,
   $$Uitwerkbijlage vraag 1, 2 en 3: leeg (v,t)-diagram van de heenreis (v van 0 tot 16 km h⁻¹, t van 0 tot 1,2 h).$$, 'uitwerkbijlage'),
  ('ff6d28d4-3481-4e45-b1f9-03d98f411dcb', '5a3d4480-353e-4e41-a142-447e160dc42c', $$uitwerkbijlage vraag 2 — leeg (v,t)-diagram van de terugreis$$,
   $$natuurkunde-havo-2016-ii-sluis-van-fankel-uitwerkbijlage-vraag2.png$$, 456,
   $$Uitwerkbijlage vraag 2 en 3: leeg (v,t)-diagram van de terugreis (v van 0 tot 16 km h⁻¹, t van 0 tot 1,2 h).$$, 'uitwerkbijlage'),
  ('2a755819-ec5a-49f7-a0e7-fc691c545e63', '5a3d4480-353e-4e41-a142-447e160dc42c', $$uitwerkbijlage vraag 4 — (h,t)-diagram van het stijgen van het water, met schrijfruimte$$,
   $$natuurkunde-havo-2016-ii-sluis-van-fankel-uitwerkbijlage-vraag4.png$$, 440,
   $$Uitwerkbijlage vraag 4: (h,t)-diagram van het stijgen van het water in de sluis (h van 0 tot 10 m, t van 0 tot 300 s), gevolgd door schrijfruimte voor de bepaling.$$, 'uitwerkbijlage'),
  ('558a8942-53e4-4a2f-b0f3-29fabf23b0b0', 'c2a80c63-ba2b-428e-88b6-6f95c76f731c', $$figuur 1 — wieg aan veer en touwen; Cveer = 1,3 kN m⁻¹, mwieg = 12,2 kg$$,
   $$natuurkunde-havo-2016-ii-wieg-context1.png$$, 440,
   $$Marloes heeft een wieg gekocht voor haar baby. De wieg hangt aan een veer en kan zachtjes op en neer trillen (zie figuur 1). Op de verpakking van de wieg staat: Cveer = 1,3 kN m⁻¹ en mwieg = 12,2 kg.

figuur 1: foto van de wieg die met touwen en een veer aan het plafond hangt.$$, 'inline'),
  ('9b7a8b4b-be68-41f3-80c4-50ca5c8854d1', 'c2a80c63-ba2b-428e-88b6-6f95c76f731c', $$wieg is met twee touwen aan het plafond bevestigd (zie figuur 1)$$,
   $$natuurkunde-havo-2016-ii-wieg-context2.png$$, 330,
   $$De wieg is met twee touwen aan het plafond bevestigd (zie figuur 1).$$, 'inline'),
  ('3425ea02-8be8-4dd6-b633-f35401959545', 'c2a80c63-ba2b-428e-88b6-6f95c76f731c', $$baby van 3,2 kg in de wieg; wieg wordt aangestoten en gaat trillen$$,
   $$natuurkunde-havo-2016-ii-wieg-context3.png$$, 436,
   $$Marloes legt haar baby van 3,2 kg in de wieg. Als zij de wieg een klein beetje naar beneden duwt en dan loslaat, gaat de wieg met de baby erin een trilling uitvoeren.$$, 'inline'),
  ('7bc245ac-17a6-405f-9b95-478a7a3cfb59', 'c2a80c63-ba2b-428e-88b6-6f95c76f731c', $$figuur 2 — cardiogram van de hartslag van de baby; papiersnelheid 50 mm s⁻¹$$,
   $$natuurkunde-havo-2016-ii-wieg-context4.png$$, 454,
   $$Marloes heeft een cardiogram van de hartslag van haar baby. Met de hartslag wordt het aantal slagen van het hart per minuut bedoeld. Het cardiogram is gegeven in figuur 2. Het papier bewoog met een snelheid van 50 mm s⁻¹.

figuur 2: cardiogram van de hartslag van de baby, met de papiersnelheid v = 50 mm s⁻¹ aangegeven.$$, 'inline'),
  ('84341f86-876e-4d3c-9895-0917ae0d1fce', 'c2a80c63-ba2b-428e-88b6-6f95c76f731c', $$wiegfrequentie moet twee keer zo klein zijn als de hartslagfrequentie van de baby; huidige wiegfrequentie is nog te hoog$$,
   $$natuurkunde-havo-2016-ii-wieg-context5.png$$, 428,
   $$Marloes heeft gelezen dat baby''s gemakkelijker in slaap vallen als de frequentie van het trillen van de wieg twee keer zo klein is als de frequentie waarmee het hart van de baby klopt. De frequentie van haar wieg is nu nog te hoog.$$, 'inline'),
  ('b95777ca-87c6-4dd5-8acb-df49f89aeaf6', 'c2a80c63-ba2b-428e-88b6-6f95c76f731c', $$uitwerkbijlage vraag 9 — touwconstructie vanaf het plafond naar de wieg$$,
   $$natuurkunde-havo-2016-ii-wieg-uitwerkbijlage-vraag9.png$$, 342,
   $$Uitwerkbijlage vraag 9: schematische tekening van de twee touwen die vanaf het plafond samenkomen bij de wieg (weergegeven als een verticaal staafje), bedoeld om de spankracht in een touw met een constructie te bepalen.$$, 'uitwerkbijlage'),
  ('534fa1be-37cf-4ac8-ad35-e726a7d9e86b', '16c00dfe-9958-49bb-ba90-c8180f1ed115', $$figuur 1 — blikseminslag boven een stad; vuistregel: 3 s tussen licht en geluid komt overeen met ongeveer 1 km afstand$$,
   $$natuurkunde-havo-2016-ii-bliksem-context1.png$$, 512,
   $$Bij onweer kunnen wolken sterk elektrisch geladen zijn. Als het bliksemt, vindt er een ontlading plaats tussen twee wolken of tussen een wolk en de aarde (een blikseminslag). Zie figuur 1. Als zo''n ontlading ver weg plaatsvindt, hoor je de donder die er bij hoort veel later dan je de lichtflits ziet. Met de volgende vuistregel kun je uitrekenen op welke afstand het onweer zich dan bevindt.

Als er drie seconden verstrijken tussen het zien van de lichtflits en het horen van de donder, bevindt het onweer zich op ongeveer één kilometer afstand.

figuur 1: foto van bliksem boven een stad bij nacht.$$, 'inline'),
  ('3d2d8171-d26b-42cc-881c-29b43fc36acd', '16c00dfe-9958-49bb-ba90-c8180f1ed115', $$KNMI: bliksem stelt weinig voor als energiebron; blikseminslag met 50 μs, 30 kA en 6,0 MV$$,
   $$natuurkunde-havo-2016-ii-bliksem-context2.png$$, 512,
   $$Op de website van het KNMI staat dat bliksem als energiebron weinig voorstelt.

De energie van een gemiddelde blikseminslag is minder dan de warmte die vrijkomt bij het verbranden van 1 m³ (Gronings) aardgas.

Bij een blikseminslag loopt er gedurende 50 μs een stroom van 30 kA tussen de donderwolk en de aarde. De spanning tussen de donderwolk en de aarde is 6,0 MV.$$, 'inline'),
  ('935a5f09-40d1-4bdc-bcf9-5b798f2db78f', '16c00dfe-9958-49bb-ba90-c8180f1ed115', $$figuur 2 — bliksemafleider op een dak; koperdraad tegenwoordig vervangen door aluminiumdraad$$,
   $$natuurkunde-havo-2016-ii-bliksem-context3.png$$, 473,
   $$Een bliksemafleider is een metalen staaf op het dak van een gebouw. Zie figuur 2. Vroeger was een bliksemafleider met een dikke koperdraad verbonden met een metalen raster in de grond. Vanwege koperdiefstal heeft men tegenwoordig het koperdraad vervangen door aluminiumdraad.

figuur 2: foto van een bliksemafleider (metalen staaf) op een dak, verbonden met een metalen raster.$$, 'inline'),
  ('b17dd723-98d1-460b-bbdb-21d7d7881e50', '16c00dfe-9958-49bb-ba90-c8180f1ed115', $$500 radioactieve bliksemafleiders (1935-1970) met radium-226 of cobalt-60; tabel op de uitwerkbijlage$$,
   $$natuurkunde-havo-2016-ii-bliksem-context4.png$$, 474,
   $$Tussen 1935 en 1970 zijn er in Nederland ongeveer 500 radioactieve bliksemafleiders op daken gezet. Op de punt van deze bliksemafleiders werd een radioactieve bron aangebracht. Men veronderstelde dat de bliksem dan eerder zou inslaan, omdat de lucht rond de bliksemafleider geïoniseerd werd door de ioniserende straling uit de bron. In sommige bliksemafleiders gebruikte men radium-226, in andere bliksemafleiders cobalt-60. Op de uitwerkbijlage staat hierover een tabel.$$, 'inline'),
  ('9233b464-da7a-4486-954c-01b84fd32d31', '16c00dfe-9958-49bb-ba90-c8180f1ed115', $$na 1970 werd ook americium-241 als radioactieve bron gebruikt$$,
   $$natuurkunde-havo-2016-ii-bliksem-context5.png$$, 389,
   $$Na 1970 werd ook americium-241 als radioactieve bron gebruikt.$$, 'inline'),
  ('1d9ebf7d-53fe-4a59-8276-1813a8828bff', '16c00dfe-9958-49bb-ba90-c8180f1ed115', $$verwijdering van radioactieve bliksemafleiders met Am-241; dosis monteur per afleider geschat op 70 μSv$$,
   $$natuurkunde-havo-2016-ii-bliksem-context6.png$$, 433,
   $$Vanwege hun niet aantoonbaar nut zijn de radioactieve bliksemafleiders enige tientallen jaren geleden door daarin gespecialiseerde bedrijven verwijderd. Per verwijderde radioactieve bliksemafleider met Am-241 werd de effectieve totale lichaamsdosis die een monteur ontvangt, geschat op 70 μSv.$$, 'inline'),
  ('74198806-f370-4203-a740-52312a597161', '16c00dfe-9958-49bb-ba90-c8180f1ed115', $$uitwerkbijlage vraag 16 — tabel met soort straling, halveringstijd en ioniserend vermogen (Ra-226, Co-60)$$,
   $$natuurkunde-havo-2016-ii-bliksem-uitwerkbijlage-vraag16.png$$, 405,
   $$Uitwerkbijlage vraag 16: in te vullen tabel met de kolommen soort straling, halveringstijd en ioniserend vermogen, voor Ra-226 (ioniserend vermogen: hoog) en Co-60 (ioniserend vermogen: laag).$$, 'uitwerkbijlage'),
  ('df492a57-ac47-4f1b-bd40-137979b3cd10', 'e0a40eb4-54fe-4a3f-b504-3fc4ffdc8216', $$figuur 1 — presentator in een kooi van aerogelplaten, van buiten verwarmd met vlammen (tv-demonstratie)$$,
   $$natuurkunde-havo-2016-ii-aerogel-context1.png$$, 287,
   $$Aerogel is een materiaal met goede warmte-isolerende eigenschappen. Bovendien is aerogel vuurbestendig. Op de Duitse televisie werd een demonstratie gegeven met aerogel. In de show wilde men laten zien dat aerogel de warmte goed isoleert. De presentator van de televisieshow ging in een kooi staan die omgeven werd door platen aerogel. De bovenkant van de ruimte was open. De platen werden aan de buitenkant met vlammen verwarmd. Zie figuur 1.

figuur 1: warmtebeeld van de presentator in een kooi van aerogelplaten die van buiten met vlammen worden verwarmd.$$, 'inline'),
  ('9b9e0920-1942-4984-ab8a-4466e4c0e0c7', 'e0a40eb4-54fe-4a3f-b504-3fc4ffdc8216', $$plaat aerogel: 1,0 cm dik, 3,0 m hoog, 1,0 m breed, massa 2,0 kg$$,
   $$natuurkunde-havo-2016-ii-aerogel-context2.png$$, 426,
   $$De gebruikte platen aerogel waren elk 1,0 cm dik, 3,0 m hoog en 1,0 m breed. Zo''n plaat heeft een massa van 2,0 kg. Een plaat van gips met dezelfde afmetingen zou veel zwaarder zijn.$$, 'inline'),
  ('22832a47-a97c-497b-abe1-cdac1d69dcea', 'e0a40eb4-54fe-4a3f-b504-3fc4ffdc8216', $$buitenkant plaat 833 °C, binnenkant 53 °C; warmtegeleidingscoëfficiënt aerogel 0,020 W m⁻¹ K⁻¹$$,
   $$natuurkunde-havo-2016-ii-aerogel-context3.png$$, 424,
   $$Aan de buitenkant werd de temperatuur van de platen aerogel 833 °C, aan de binnenkant was de temperatuur van de platen ''slechts'' 53 °C. Aerogel heeft een warmtegeleidingscoëfficiënt van 0,020 W m⁻¹ K⁻¹.$$, 'inline'),
  ('e507a565-aa94-455e-ad18-63c771416654', 'e0a40eb4-54fe-4a3f-b504-3fc4ffdc8216', $$spouwmuur met luchtspouw of isolatiemateriaal; lucht is een slechte warmtegeleider en staat stil in de spouw$$,
   $$natuurkunde-havo-2016-ii-aerogel-context4.png$$, 433,
   $$In een huis bestaan de buitenmuren meestal uit twee stenen muren met een ruimte ertussen: de spouw. De spouw kan lucht bevatten of kan gevuld zijn met een isolatiemateriaal. Lucht is een slechte warmtegeleider. Neem aan dat de lucht in de spouw stilstaat.$$, 'inline'),
  ('76ef79cd-42d1-409c-a5da-cd21afe3310c', 'e0a40eb4-54fe-4a3f-b504-3fc4ffdc8216', $$figuur 2 en 3 — temperatuurverloop over de muurdikte bij een spouw gevuld met aerogel resp. polystyreen$$,
   $$natuurkunde-havo-2016-ii-aerogel-context5.png$$, 440,
   $$Een spouwmuur kan geïsoleerd worden door de spouw te vullen met polystyreen of met aerogel. In figuur 2 is het temperatuurverloop als functie van de dikte van de muren gegeven voor aerogel; in figuur 3 voor polystyreen. De buitenmuren en binnenmuren zijn in beide situaties identiek.

figuur 2: temperatuurverloop (T van −15 tot 25 °C) als functie van de dikte van de muur (0-250 mm) bij een spouw gevuld met aerogel (spouw tussen 100 en 150 mm); T loopt van ongeveer −11 °C buiten via ongeveer 17 °C net na de spouw naar 20 °C binnen.
figuur 3: hetzelfde temperatuurverloop bij een spouw gevuld met polystyreen; T loopt van ongeveer −11 °C buiten via ongeveer 16 °C net na de spouw naar 20 °C binnen.$$, 'inline'),
  ('5016b7ae-a8a5-4cf3-88c9-edafad056833', 'e0a40eb4-54fe-4a3f-b504-3fc4ffdc8216', $$uitwerkbijlage vraag 22 — tabel met vier uitspraken, aan te kruisen als waar of niet waar$$,
   $$natuurkunde-havo-2016-ii-aerogel-uitwerkbijlage-vraag22.png$$, 490,
   $$Uitwerkbijlage vraag 22: tabel met de vier uitspraken (1: de warmtegeleidingscoëfficiënt van polystyreen is groter dan van aerogel; 2: het temperatuurverschil over de spouw met polystyreen is groter dan bij aerogel; 3: de warmtestroom tussen binnen en buiten is voor beide muren gelijk; 4: polystyreen isoleert beter dan aerogel), met aan te kruisen kolommen ''waar'' en ''niet waar''.$$, 'uitwerkbijlage'),
  ('65f7a709-6414-45fc-8689-213f523f924f', 'ac555faa-7897-450c-8dca-3e3856d1e765', $$Airbus E-fan: twee motoren van 4,0 kW, elk met een eigen accu van 250 V; loskomen van de grond bij 32 knopen$$,
   $$natuurkunde-havo-2016-ii-airbus-e-fan-context1.png$$, 462,
   $$De Airbus E-fan is een klein, tweepersoons elektrisch vliegtuig. Het vliegtuig heeft twee motoren met een vermogen van 4,0 kW per motor. Elke motor heeft een eigen accu, met een spanning van 250 V. De E-fan maakte zijn eerste vlucht op 11 maart 2014 op een luchtshow in Engeland. Het vliegtuig kwam los van de grond bij een snelheid van 32 knopen.

foto: de Airbus E-fan tijdens de vlucht.$$, 'inline'),
  ('55ebe328-1a90-41fc-b242-633463418954', 'ac555faa-7897-450c-8dca-3e3856d1e765', $$bij maximaal vermogen van 4,0 kW kan een motor maximaal 1 uur en 10 minuten werken; massa van een accu is 40 kg$$,
   $$natuurkunde-havo-2016-ii-airbus-e-fan-context2.png$$, 444,
   $$Bij een maximaal vermogen van 4,0 kW kan een motor maximaal 1 uur en 10 minuten werken. De massa van een accu is 40 kg.$$, 'inline'),
  ('22bcb2ec-bf07-417e-8f3b-59e7f104e7fe', 'ac555faa-7897-450c-8dca-3e3856d1e765', $$beide motoren en beide accu''s in één schakeling; bij uitval van één motor moet de andere blijven werken; drie schakelingen op de uitwerkbijlage$$,
   $$natuurkunde-havo-2016-ii-airbus-e-fan-context3.png$$, 433,
   $$In plaats van elke motor op zijn eigen accu aan te sluiten, worden beide motoren en beide accu''s in één schakeling aangesloten. Als één motor uitvalt, moet de andere wel blijven werken. Op de uitwerkbijlage staan drie schakelingen getekend.$$, 'inline'),
  ('d57c411c-cab1-44a0-91a4-4d913dfb68c6', 'ac555faa-7897-450c-8dca-3e3856d1e765', $$hybride variant: accu''s worden opgeladen door een verbrandingsmotor op benzine; 2,5 uur langer in de lucht; rendement verbrandingsmotor 35%$$,
   $$natuurkunde-havo-2016-ii-airbus-e-fan-context4.png$$, 443,
   $$Omdat het vliegtuig slechts korte vluchten kan maken op de twee volle accu''s, wil de fabrikant een hybride model op de markt brengen dat langere vluchten kan maken. In deze variant worden de accu''s opgeladen door een verbrandingsmotor op benzine. Deze variant kan 2,5 uur langer in de lucht blijven dan de E-fan. Het rendement van de verbrandingsmotor is 35%.$$, 'inline'),
  ('540750a3-0073-41a4-95c3-0ae32a15447a', 'ac555faa-7897-450c-8dca-3e3856d1e765', $$uitwerkbijlage vraag 26 — drie schakelschema''s (I, II, III) met twee accu''s en twee motoren$$,
   $$natuurkunde-havo-2016-ii-airbus-e-fan-uitwerkbijlage-vraag26.png$$, 490,
   $$Uitwerkbijlage vraag 26: drie schakelschema''s. Schema I: bovenste tak met één accu, middelste tak met één accu (beide accu''s parallel), onderste tak met twee motoren M in serie. Schema II: bovenste tak met twee accu''s in serie, middelste tak met één motor M, onderste tak met één motor M (beide motoren parallel aan de in serie geschakelde accu''s). Schema III: twee takken met elk één accu en een derde, open verbindingstak, met één motor M in de schakeling getekend en een tweede motor M los buiten de schakeling getekend.$$, 'uitwerkbijlage');

